// 1. ko.ts 및 types.ts 갱신
const koContent = fs.readFileSync(koFile, 'utf8');
const keyToKo = {};

const lines = koContent.split('\n');
for (const line of lines) {
  const match = line.match(/^\s*([a-zA-Z0-9_]+):\s*(.*),?$/);
  if (match) {
    const key = match[1];
    try {
      const rawVal = match[2].trim().replace(/,$/, '');
      const val = JSON.parse(rawVal);
      if (typeof val === 'string' && val.trim()) {
        keyToKo[key] = val;
      }
    } catch (e) {}
  }
}

// 신규 키 등록
for (const [k, obj] of Object.entries(NEW_MASTER_KEYS)) {
  keyToKo[k] = obj.ko;
}

// types.ts 작성
const typeLines = [
  `// K-Market 17개국어 표준 번역 키 마스터 인터페이스`,
  ``,
  `export interface TranslationDictionary {`,
];
for (const key of Object.keys(keyToKo)) {
  typeLines.push(`  ${key}: string;`);
}
typeLines.push(`}`, ``);
fs.writeFileSync(typesFile, typeLines.join('\n'), 'utf8');
console.log(`✅ Updated types.ts with ${Object.keys(keyToKo).length} keys`);

// ko.ts 작성
const koOutLines = [
  `import { TranslationDictionary } from '../types';`,
  ``,
  `export const ko: TranslationDictionary = {`,
];
for (const [k, v] of Object.entries(keyToKo)) {
  koOutLines.push(`  ${k}: ${JSON.stringify(v)},`);
}
koOutLines.push(`};`, ``);
fs.writeFileSync(koFile, koOutLines.join('\n'), 'utf8');
console.log(`✅ Updated ko.ts`);

// 17개 언어 파일 전체 동기화
const targetLanguages = ['en', 'zh', 'vi', 'ja', 'ru', 'th', 'uz', 'km', 'mn', 'ne', 'id', 'my', 'si', 'kk', 'bn', 'ur', 'tl'];

for (const lang of targetLanguages) {
  const filePath = path.join(localesDir, `${lang}.ts`);
  let existingEntries = {};

  if (fs.existsSync(filePath)) {
    const content = fs.readFileSync(filePath, 'utf8');
    const lns = content.split('\n');
    for (const line of lns) {
      const match = line.match(/^\s*([a-zA-Z0-9_]+):\s*(.*),?$/);
      if (match) {
        try {
          const raw = match[2].trim().replace(/,$/, '');
          const val = JSON.parse(raw);
          if (typeof val === 'string') {
            existingEntries[match[1]] = val;
          }
        } catch (e) {}
      }
    }
  }

  const resultEntries = {};
  for (const [key, koVal] of Object.entries(keyToKo)) {
    if (NEW_MASTER_KEYS[key] && NEW_MASTER_KEYS[key][lang]) {
      resultEntries[key] = NEW_MASTER_KEYS[key][lang];
    } else if (existingEntries[key]) {
      resultEntries[key] = existingEntries[key];
    } else {
      resultEntries[key] = koVal;
    }
  }

  const outLines = [
    `import { TranslationDictionary } from '../types';`,
    ``,
    `export const ${lang}: TranslationDictionary = {`,
  ];
  for (const [k, v] of Object.entries(resultEntries)) {
    outLines.push(`  ${k}: ${JSON.stringify(v || '')},`);
  }
  outLines.push(`};`, ``);
  fs.writeFileSync(filePath, outLines.join('\n'), 'utf8');
  console.log(`✅ Fully synchronized ${lang}.ts (${Object.keys(resultEntries).length} keys)`);
}

console.log('🎉 ALL 17 LANGUAGES MIRRORED AND SYNCHRONIZED PERFECTLY!');
